CREATE   PROCEDURE [synapse_fo].[usp_Insert_WORKFLOWTRACKINGSTATUSTABLE]
AS
BEGIN

	INSERT INTO [synapse_fo].[WORKFLOWTRACKINGSTATUSTABLE]
	(
		[Id],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[trackingstatus],
		[workflowtype],
		[sysdatastatecode],
		[instancenumber],
		[configurationname],
		[configurationnumber],
		[configurationversionid],
		[contextcompanyid],
		[contextrecid],
		[contexttableid],
		[correlationid],
		[document],
		[documenttype],
		[originator],
		[owner],
		[parentcorrelationid],
		[rootcorrelationid],
		[subworkflowid],
		[workflowversiontable],
		[modifieddatetime],
		[modifiedby],
		[modifiedtransactionid],
		[createddatetime],
		[createdby],
		[createdtransactionid],
		[dataareaid],
		[recversion],
		[partition],
		[sysrowversion],
		[recid],
		[tableid],
		[versionnumber],
		[createdon],
		[modifiedon],
		[IsDelete],
		[PartitionId]
	)
	SELECT 
		wrk.[Id],
		wrk.[SinkCreatedOn],
		wrk.[SinkModifiedOn],
		wrk.[trackingstatus],
		wrk.[workflowtype],
		wrk.[sysdatastatecode],
		wrk.[instancenumber],
		wrk.[configurationname],
		wrk.[configurationnumber],
		wrk.[configurationversionid],
		wrk.[contextcompanyid],
		wrk.[contextrecid],
		wrk.[contexttableid],
		wrk.[correlationid],
		wrk.[document],
		wrk.[documenttype],
		wrk.[originator],
		wrk.[owner],
		wrk.[parentcorrelationid],
		wrk.[rootcorrelationid],
		wrk.[subworkflowid],
		wrk.[workflowversiontable],
		wrk.[modifieddatetime],
		wrk.[modifiedby],
		wrk.[modifiedtransactionid],
		wrk.[createddatetime],
		wrk.[createdby],
		wrk.[createdtransactionid],
		wrk.[dataareaid],
		wrk.[recversion],
		wrk.[partition],
		wrk.[sysrowversion],
		wrk.[recid],
		wrk.[tableid],
		wrk.[versionnumber],
		wrk.[createdon],
		wrk.[modifiedon],
		wrk.[IsDelete],
		wrk.[PartitionId]
	FROM [staging_fo].[WORKFLOWTRACKINGSTATUSTABLE] wrk
		LEFT JOIN [synapse_fo].[WORKFLOWTRACKINGSTATUSTABLE] tgt
			ON wrk.[recid] = tgt.[recid]
	WHERE tgt.[recid] IS NULL

END
